from reportlab.lib import colors
from reportlab.lib.colors import HexColor
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

OUT='output/pdf/BrandProof_Round_3_Project_Report.pdf'; GREEN=HexColor('#365C45'); INK=HexColor('#26332A'); MUTED=HexColor('#657168'); PALE=HexColor('#EFF3ED'); GOLD=HexColor('#F7EED9')
doc=SimpleDocTemplate(OUT,pagesize=A4,leftMargin=18*mm,rightMargin=18*mm,topMargin=18*mm,bottomMargin=18*mm,title='BrandProof - Round 3 Project Report',author='Muted Mavericks',subject='Round 3 completion report')
s=getSampleStyleSheet();s.add(ParagraphStyle(name='cover',parent=s['Title'],fontName='Helvetica-Bold',fontSize=32,leading=36,textColor=INK,alignment=TA_LEFT,spaceAfter=5*mm));s.add(ParagraphStyle(name='deck',parent=s['BodyText'],fontSize=11,leading=16,textColor=MUTED,spaceAfter=4*mm));s.add(ParagraphStyle(name='h1x',parent=s['Heading1'],fontName='Helvetica-Bold',fontSize=20,leading=24,textColor=INK,spaceBefore=1*mm,spaceAfter=3*mm));s.add(ParagraphStyle(name='h2x',parent=s['Heading2'],fontName='Helvetica-Bold',fontSize=11,leading=14,textColor=GREEN,spaceBefore=2.5*mm,spaceAfter=1.2*mm));s.add(ParagraphStyle(name='bodyx',parent=s['BodyText'],fontSize=8.8,leading=12,textColor=INK,spaceAfter=1.6*mm));s.add(ParagraphStyle(name='smallx',parent=s['BodyText'],fontSize=7.5,leading=9.5,textColor=MUTED,spaceAfter=1*mm));s.add(ParagraphStyle(name='thx',parent=s['BodyText'],fontName='Helvetica-Bold',fontSize=7.5,leading=9,textColor=colors.white));s.add(ParagraphStyle(name='tdx',parent=s['BodyText'],fontSize=7.4,leading=9.4,textColor=INK));s.add(ParagraphStyle(name='callx',parent=s['BodyText'],fontSize=8.6,leading=12,textColor=INK))
P=lambda t,style='bodyx':Paragraph(t,s[style]);B=lambda t:P('&bull;&nbsp; '+t)
def table(rows,widths):
 data=[[P(str(c),'thx' if i==0 else 'tdx') for c in row] for i,row in enumerate(rows)]
 x=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT');x.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),GREEN),('GRID',(0,0),(-1,-1),.35,HexColor('#DDE3DA')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4)]));return x
def call(text,bg=PALE):
 x=Table([[P(text,'callx')]],colWidths=[doc.width]);x.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,-1),bg),('BOX',(0,0),(-1,-1),.5,HexColor('#DDE3DA')),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7)]));return x
def link(url,label):return f'<link href="{url}" color="#365C45"><u>{label}</u></link>'
def hf(c,d):
 c.saveState();w,h=A4
 if d.page>1:c.setStrokeColor(HexColor('#DDE3DA'));c.line(18*mm,h-12*mm,w-18*mm,h-12*mm);c.setFont('Helvetica-Bold',7.5);c.setFillColor(GREEN);c.drawString(18*mm,h-9*mm,'BRANDPROOF / ROUND 3 PROJECT REPORT')
 c.setStrokeColor(HexColor('#DDE3DA'));c.line(18*mm,12*mm,w-18*mm,12*mm);c.setFont('Helvetica',7.5);c.setFillColor(MUTED);c.drawString(18*mm,8*mm,'Muted Mavericks | Inkloom AI');c.drawRightString(w-18*mm,8*mm,str(d.page));c.restoreState()

story=[Spacer(1,13*mm),P('INKLOOM AI / ROUND 3 SUBMISSION','h2x'),P('BrandProof','cover'),P('A human-led brand governance workspace: compare content with team rules and approved evidence, review findings, and record decisions against the exact content version. This report says what is implemented, what passed local checks, and what still depends on provider or hosting setup.','deck'),call('<b>Report date: 29 October 2026</b><br/>The code work described below is in the current working copy. The public Render service has not yet been updated from this copy. The latest user-shared production screenshot showed Groq HTTP 403. The optional paid persistent profile is prepared but not deployed.' ,GOLD),Spacer(1,5*mm),table([['SUBMISSION ITEM','DETAIL'],['Live project',link('https://brandproof-95p8.onrender.com','brandproof-95p8.onrender.com (current demo URL)')],['Source repository',link('https://github.com/srushti234oss/BrandProofAI','github.com/srushti234oss/BrandProofAI')],['Team','Muted Mavericks - Sathwikaa, Soumya H, Srushti Shelar, Bhavana K'],['Event','Inkloom AI - Intelligent Brand Governance']],[38*mm,doc.width-38*mm]),P('Judge path','h2x'),P('Register and create a workspace; add a real guideline, structured rule and approved evidence; submit text or a supported file; inspect findings; record a human decision; open the versioned Trust Receipt. The app does not seed sample workspace data. Use a fresh account rather than treating the earlier BrightBite screenshot as verified evidence.','bodyx'),P('Status terms','h2x'),P('<b>Implemented</b> means code is present. <b>Locally verified</b> means checks passed in this environment. <b>Pending live setup</b> means judge-facing deployment/provider behavior still needs owner configuration and a fresh check.','bodyx'),PageBreak()]

story += [P('01 / Features implemented','h1x'),P('Core account-to-review flow','h2x')]
features=[['FEATURE','WHAT WORKS','LIMIT / STATUS'],['Accounts/workspaces','Registration, login, workspace membership, invitations, role-aware permissions.','SMTP optional; manual invitation links work.'],['Brand guidelines','Paste/upload guideline source, version history, create/edit rules, approved examples.','Document extraction may return warnings.'],['Evidence and claims','Add/upload evidence, approve/revoke it, retrieve approved workspace evidence, link sources to claims, reviewer adjudication.','Missing evidence stays unverified; it is not called false.'],['Content intake','Pasted copy, TXT/PDF/DOCX/PNG/JPEG to 20 MB; extraction metadata, warnings, source retention.','OCR needs Tesseract.'],['Risk Radar','Deterministic term/claim rules, optional structured LLM analysis, cautious correction suggestions.','AI is advisory; latest user screenshot showed Groq HTTP 403.'],['Campaign Consistency','Across latest readable versions in a named campaign: changed numbers in repeated sentence patterns, configured preferred-wording variants, recognized disclaimer-marker presence. Exact asset/version/wording shown.','Conservative signals for human review. Does not judge truth, legal compliance, paraphrases, or format-specific disclosure requirements.'],['Review and audit','Comments, reviewer assignment, status history, approve/request changes/reject, corrections as new versions, Trust Receipt and audit history.','Approval stays bound to its exact content version.'],['Clarity and visual checks','Repeated review signals can suggest guideline clarification; palette/logo/selected contrast checks run when references exist.','Simple signal threshold; visual results are heuristic/advisory.']]
story += [table(features,[33*mm,86*mm,doc.width-119*mm]),Spacer(1,3*mm),P('Core data flow','h2x'),P('<b>Configure guidelines and approved evidence → submit content → extract text and preserve provenance → deterministic checks plus optional AI/retrieval → human resolves findings and decides → version hash, receipt and audit history.</b>','bodyx'),P('No demo seeding','h2x'),P('The standard Render startup only runs database migrations. The team or judge creates an account and enters its own workspace information. `seed_demo` is an optional local walkthrough command and is not run by either Blueprint.','bodyx'),PageBreak()]

story += [P('02 / Three Round 2 improvements','h1x'),P('Progress against the exact commitments','h2x')]
for name,status,body in [
('1. Campaign-wide consistency review','WORKING FIRST RELEASE IMPLEMENTED','A new workspace-scoped screen/API compares latest readable versions of same-name campaigns. It flags numeric differences in repeated sentence structures, presence/absence of configured preferred wording, and presence/absence of recognized disclaimer markers. It shows both passages and versions. It remains a rules-based, conservative check: no semantic paraphrase comparison, legal decision, or determination of which claim is correct.'),
('2. Indexed hybrid evidence search','IMPLEMENTED IN CODE; LIVE PGVECTOR PATH NOT VERIFIED','Added an EmbeddingIndex model, a PostgreSQL migration that creates the pgvector HNSW cosine index, and reciprocal-rank fusion of semantic and lexical retrieval. Retrieval rechecks current workspace, approval and guideline version. SQLite/unavailable vector cases retain JSON cosine and lexical fallbacks. Database-side ranking needs PostgreSQL/vector extension and a compatible embeddings provider returning 1536 dimensions.'),
('3. Persistent, resilient deployment','SEPARATE PAID PROFILE PREPARED; NOT LIVE','`render.persistent.yaml` defines separate web and analysis-worker services with a dedicated PostgreSQL database and private S3-compatible upload storage. It applies migrations at web startup, shares DB/storage config with the worker, and enables up to three analysis attempts with backoff plus stale-job recovery. It requires paid Render resources and external storage credentials; it has not been created or tested. Backups, restore and monitoring still need owner setup and verification.')]:
 story += [P(name,'h2x'),P('<b>'+status+'</b>','smallx'),P(body,'bodyx')]
story += [call('<b>External steps still required:</b> push this working copy to GitHub, deploy it, configure the isolated database/storage/provider, then run the judge journey on the new URL. The existing live demo link may still serve the old commit and temporary data.' ,GOLD),PageBreak()]

story += [P('03 / Technical architecture','h1x'),P('Single-origin React + Django application. The Docker build bundles the frontend into the Django service; session authentication and CSRF keep browser/API calls on one origin.','bodyx')]
arch=[['LAYER','IMPLEMENTATION'],['Frontend','React, TypeScript, Vite; client-side workspace and review screens.'],['API','Python, Django, Django REST Framework; ORM, session auth, CSRF, role checks, request throttling.'],['Database','SQLite by default locally and in temporary demo; PostgreSQL through DATABASE_URL in durable profile.'],['AI','Optional OpenAI-compatible chat and embedding endpoints; secrets supplied by host environment.'],['Retrieval','Approved evidence and current guideline chunks. Hybrid semantic + lexical reciprocal-rank fusion. pgvector HNSW for supported PostgreSQL vectors; portable JSON/lexical fallback.'],['Documents/images','PyPDF, python-docx, PyMuPDF, Tesseract, Pillow, OpenCV; original source through Django storage.'],['Jobs','Database-backed AnalysisRun state machine; retries/backoff and stale processing recovery in worker command.'],['Render profiles','render.yaml: free single service and ephemeral SQLite/media. render.persistent.yaml: paid web + separate worker + PostgreSQL + private S3-compatible media.']]
story += [table(arch,[39*mm,doc.width-39*mm]),P('Workspace protections','h2x'),B('Evidence retrieval filters to current workspace and approved source records; pgvector candidates are rechecked before use.'),B('Guideline retrieval filters to current guideline version.'),B('Corrections make a new version; old reviewer decisions remain on the old version.'),B('AI/provider failure retains deterministic findings and unverified claim triage instead of implying compliance.'),PageBreak()]

story += [P('04 / Reliability and testing','h1x'),P('Hardening added','h2x'),B('Dashboard loads panels independently; one failed API request no longer blanks all dashboard content.'),B('Malformed non-text asset fields return HTTP 400 rather than causing string-operation errors.'),B('Repeated identical review decisions are idempotent for the same reviewer and version.'),B('Repeated retry click returns the existing queued/processing job.'),B('Worker can retry a failed analysis up to three times with backoff; stale processing work is reclaimed.'),P('Checks run','h2x'),table([['CHECK','RESULT'],['Frontend production build','PASS - TypeScript build and Vite bundle.'],['Django system check','PASS - no issues.'],['Migration consistency','PASS - no model migration pending.'],['Focused campaign/retrieval/retry checks','PASS - campaign numeric/wording/disclosure, workspace approval scope, vector index mirror, and worker retries.'],['End-to-end API flow','PASS - fresh registration, workspace, guideline/rule, approved evidence, content analysis, review and Trust Receipt.'],['Runnable backend suite','46 tests pass; the one remaining schema test cannot run here because global Python lacks `inflection`. It is listed in backend requirements. Install `pip install -r requirements.txt` to run all tests.']],[49*mm,doc.width-49*mm]),P('What is not verified yet','h2x'),B('Full local suite: one API schema test blocked by missing local `inflection`; not a product code failure, but still needs rerun after dependency installation.'),B('Hosted service: latest user screenshot shows Groq HTTP 403. Enable key/model access and run a fresh review.'),B('PostgreSQL/pgvector and embedding provider integration have not been exercised against the hosted database.'),B('Persistent profile has not been deployed; S3 credentials, backup/restore and health monitoring are not configured.'),B('Free demo persists neither database nor uploads across restarts/redeploys.'),PageBreak()]

story += [P('05 / Changes, roadmap and submission checklist','h1x'),P('Changes from the original proposal','h2x'),P('Round 1 proposed PostgreSQL/pgvector, broader campaign comparison, multimodal analysis and production-ready retention. Round 2 delivered the human-led workflow and disclosed that free demo storage, provider permission and pgvector hosting were incomplete. Round 3 adds a first campaign consistency product surface, indexed hybrid search code, and an opt-in durable infrastructure profile. The live external setup remains a required team action; no production success is claimed before it is tested.','bodyx'),P('Before submitting','h2x'),B('Commit and push this working copy; confirm the final GitHub repository link points to that commit.'),B('Choose whether to create the paid Render profile; check current service/database and storage costs first.'),B('Add the isolated S3-compatible bucket and Groq secrets in Render, then wait for web, worker and database health.'),B('Run a fresh account journey; compare two campaign assets; upload/download a private file; review and open a receipt; refresh and verify persistence.'),B('After fixing Groq 403, create new content and confirm the analysis warning clears; verify AI and pgvector settings explicitly.'),B('Install backend requirements and rerun all tests; inspect Render build/deploy logs.'),B('Update the final URL here and in the submission form only after successful deployment.'),P('Roadmap','h2x'),table([['STAGE','PRODUCT PLAN'],['Round 3 close','Validate numeric, preferred-wording and disclaimer comparison on real campaign examples; validate hosted hybrid retrieval; deploy persistent profile and test worker restart/redeploy/file persistence.'],['Next','Configure and test DB backups/restoration, S3 lifecycle/retention, worker/web/database alerts, and document an incident/recovery runbook.'],['Later','Build a labelled campaign benchmark for paraphrases and format-specific disclosures; measure retrieval precision/recall and latency; expand onboarding and reviewer exports.']],[31*mm,doc.width-31*mm]),Spacer(1,2*mm),call('BrandProof supports human review. It does not certify factual truth, legal compliance, accessibility compliance or publication safety. Final decisions belong to an authorised reviewer.'),Spacer(1,2*mm),P('Project: '+link('https://brandproof-95p8.onrender.com','current demo URL')+' | Repository: '+link('https://github.com/srushti234oss/BrandProofAI','BrandProofAI'),'smallx')]
doc.build(story,onFirstPage=hf,onLaterPages=hf)
